/* ==========================================================================
   PRIMITIVES — raw values. Never referenced directly by components.
   Components use semantic tokens (semantic.css) only.
   All color pairs below are APCA-verified. Regenerate: node tools/generate-scales.mjs
   ========================================================================== */

:root {
  /* ---- Gray scale (OKLCH, hue 260, chroma 0.005) ---- */
  --gray-50:  oklch(0.985 0.005 260);
  --gray-100: oklch(0.967 0.005 260);
  --gray-200: oklch(0.922 0.005 260);
  --gray-300: oklch(0.869 0.005 260);
  --gray-400: oklch(0.788 0.005 260);
  --gray-500: oklch(0.582 0.005 260);
  --gray-600: oklch(0.446 0.005 260);
  --gray-700: oklch(0.373 0.005 260);
  --gray-750: oklch(0.325 0.005 260);
  --gray-800: oklch(0.279 0.005 260);
  --gray-900: oklch(0.208 0.005 260);
  --gray-925: oklch(0.175 0.005 260);
  --gray-950: oklch(0.137 0.005 260);

  --white: oklch(1 0 0);
  --black: oklch(0 0 0);
  --overlay-50: oklch(0 0 0 / 0.5);

  /* ---- Status: error (hue 25) ---- */
  --error-bg:          oklch(0.96 0.0475 25);
  --error-border:      oklch(0.85 0.095 25);
  --error-base:        oklch(0.59 0.19 25);
  --error-text:        oklch(0.37 0.19 25);
  --error-bg-dark:     oklch(0.22 0.0665 25);
  --error-border-dark: oklch(0.34 0.095 25);
  --error-base-dark:   oklch(0.96 0.12 25);
  --error-text-dark:   oklch(0.98 0.12 25);

  /* ---- Status: warning (hue 75) ---- */
  --warning-bg:          oklch(0.96 0.0375 75);
  --warning-border:      oklch(0.85 0.075 75);
  --warning-base:        oklch(0.62 0.15 75);
  --warning-text:        oklch(0.40 0.15 75);
  --warning-bg-dark:     oklch(0.22 0.0525 75);
  --warning-border-dark: oklch(0.34 0.075 75);
  --warning-base-dark:   oklch(0.72 0.15 75);
  --warning-text-dark:   oklch(0.90 0.11 75);

  /* ---- Status: success (hue 150) ---- */
  --success-bg:          oklch(0.96 0.03 150);
  --success-border:      oklch(0.85 0.06 150);
  --success-base:        oklch(0.62 0.12 150);
  --success-text:        oklch(0.38 0.12 150);
  --success-bg-dark:     oklch(0.22 0.042 150);
  --success-border-dark: oklch(0.34 0.06 150);
  --success-base-dark:   oklch(0.72 0.12 150);
  --success-text-dark:   oklch(0.88 0.10 150);

  /* ---- Status: info (hue 240) ---- */
  --info-bg:          oklch(0.96 0.035 240);
  --info-border:      oklch(0.85 0.07 240);
  --info-base:        oklch(0.62 0.14 240);
  --info-text:        oklch(0.38 0.14 240);
  --info-bg-dark:     oklch(0.22 0.049 240);
  --info-border-dark: oklch(0.34 0.07 240);
  --info-base-dark:   oklch(0.72 0.14 240);
  --info-text-dark:   oklch(0.90 0.11 240);

  /* ---- Brand slots (overridden per project in theme.css) ---- */
  /* Defaults are neutral so an unthemed project still ships accessible UI.
     Two roles, deliberately separate: action is what the user clicks, base is
     what the brand looks like. They are often not the same color. */
  --brand-action:        var(--gray-900);
  --brand-action-hover:  var(--gray-800);
  --brand-action-text:   var(--white);     /* text ON the action color, verify APCA when overriding */
  --brand-base:          oklch(0.62 0.14 240);
  --brand-base-subtle:   oklch(0.96 0.035 240);

  /* ---- Type scale (px values via rem, 14px floor is LAW — see RULES.md N2) ---- */
  --font-sans: system-ui, -apple-system, sans-serif;   /* overridden in theme.css */
  --font-mono: ui-monospace, 'SF Mono', monospace;

  --text-sm:   0.875rem;   /* 14px — MINIMUM. Nothing smaller exists. */
  --text-base: 1rem;       /* 16px */
  --text-lg:   1.125rem;   /* 18px */
  --text-xl:   1.25rem;    /* 20px */
  --text-2xl:  1.5rem;     /* 24px */
  --text-3xl:  1.875rem;   /* 30px */
  --text-4xl:  2.25rem;    /* 36px */

  --leading-sm:   1.5;     /* for text-sm/base */
  --leading-md:   1.4;     /* for text-lg/xl */
  --leading-tight: 1.2;    /* for headings 2xl+ */

  --tracking-normal: 0;
  --tracking-tight: -0.01em;  /* headings only */
  /* No wide/uppercase tracking token exists on purpose. See RULES.md N1. */

  /* ---- Spacing (4px base) ---- */
  --space-1: 0.25rem;  --space-2: 0.5rem;   --space-3: 0.75rem;
  --space-4: 1rem;     --space-5: 1.25rem;  --space-6: 1.5rem;
  --space-8: 2rem;     --space-10: 2.5rem;  --space-12: 3rem;
  --space-16: 4rem;    --space-20: 5rem;    --space-24: 6rem;

  /* ---- Radius ---- */
  --radius-sm: 0.375rem;  /* 6px — inputs, small controls */
  --radius-md: 0.5rem;    /* 8px — buttons, cards */
  --radius-lg: 0.75rem;   /* 12px — dialogs, large surfaces */
  --radius-full: 9999px;

  /* ---- Elevation ---- */
  --shadow-sm: 0 1px 2px oklch(0 0 0 / 0.05);
  --shadow-md: 0 2px 8px oklch(0 0 0 / 0.08), 0 1px 2px oklch(0 0 0 / 0.04);
  --shadow-lg: 0 8px 24px oklch(0 0 0 / 0.12), 0 2px 6px oklch(0 0 0 / 0.06);

  /* ---- Motion ---- */
  --duration-fast: 120ms;    /* hover, focus */
  --duration-base: 180ms;    /* dropdowns, tooltips */
  --duration-slow: 260ms;    /* dialogs, sheets */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);

  /* ---- Z-index scale ---- */
  --z-dropdown: 50;
  --z-sticky: 100;
  --z-overlay: 200;
  --z-dialog: 300;
  --z-toast: 400;
  --z-tooltip: 500;

  /* ---- Layout ---- */
  --touch-target-min: 44px;  /* minimum interactive hit area */
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;
}

/* Dark-mode defaults for brand slots. Projects override these in theme.css
   (.dark block). semantic.css consumes var(--brand-*) in BOTH modes, so
   contrast-check verifies pairs that are actually rendered. */
.dark {
  --brand-action:       var(--gray-50);
  --brand-action-hover: var(--gray-200);
  --brand-action-text:  var(--gray-950);
  --brand-base:        oklch(0.72 0.14 240);
  --brand-base-subtle: oklch(0.24 0.049 240);
}

/* ==========================================================================
   SEMANTIC TOKENS — the ONLY color layer components may reference.
   Light mode on :root, dark mode on .dark.
   Every text/surface pair here is APCA-verified (tools/generate-scales.mjs).
   ========================================================================== */

:root {
  /* ---- Surfaces ---- */
  --color-canvas:          var(--gray-50);    /* app background */
  --color-surface:         var(--white);      /* cards, panels */
  --color-surface-raised:  var(--white);      /* dialogs, popovers (pairs with shadow) */
  --color-surface-sunken:  var(--gray-100);   /* wells, code blocks, table headers */
  --color-surface-hover:   var(--gray-100);
  --color-surface-active:  var(--gray-200);

  /* ---- Text ---- */
  --color-text-primary:    var(--gray-950);   /* Lc 103+ on canvas */
  --color-text-secondary:  var(--gray-700);   /* Lc 91 — body text on canvas */
  /* Tertiary tier (Lc 60+): meta text only: hints, timestamps, placeholders.
     Never body copy, and never on hover/active surfaces (use secondary there). */
  --color-text-tertiary:   var(--gray-600);   /* Lc 83 — hints, meta. LOWEST allowed for text */
  --color-text-disabled:   var(--gray-400);   /* disabled states only, never for readable content */
  --color-text-inverse:    var(--white);
  --color-text-link:       var(--info-text);

  /* ---- Borders ---- */
  --color-border:          var(--gray-300);
  --color-border-subtle:   var(--gray-200);
  --color-border-strong:   var(--gray-400);

  /* ---- Interactive ----
     action = what the user clicks (filled buttons, primary CTAs).
     brand  = the brand's identity color (selection tints, highlights).
     These are named by role, not by rank. A brand color mapped onto
     buttons because it was called "primary" is a real bug we have shipped. */
  --color-action:          var(--brand-action);
  --color-action-hover:    var(--brand-action-hover);
  --color-action-text:     var(--brand-action-text);
  --color-brand:           var(--brand-base);
  --color-brand-subtle:    var(--brand-base-subtle);
  --color-focus-ring:      var(--info-base);
  --color-text-on-status:  var(--white);     /* text on solid status colors (destructive buttons) */
  --color-overlay:         var(--overlay-50); /* dialog/sheet scrim */

  /* ---- Status (bg/border/base/text per status; base = icons and large UI) ---- */
  --color-status-error-bg:       var(--error-bg);
  --color-status-error-border:   var(--error-border);
  --color-status-error:          var(--error-base);
  --color-status-error-text:     var(--error-text);

  --color-status-warning-bg:     var(--warning-bg);
  --color-status-warning-border: var(--warning-border);
  --color-status-warning:        var(--warning-base);
  --color-status-warning-text:   var(--warning-text);

  --color-status-success-bg:     var(--success-bg);
  --color-status-success-border: var(--success-border);
  --color-status-success:        var(--success-base);
  --color-status-success-text:   var(--success-text);

  --color-status-info-bg:        var(--info-bg);
  --color-status-info-border:    var(--info-border);
  --color-status-info:           var(--info-base);
  --color-status-info-text:      var(--info-text);
}

.dark {
  --color-canvas:          var(--gray-950);
  --color-surface:         var(--gray-900);
  --color-surface-raised:  var(--gray-800);
  --color-surface-sunken:  var(--gray-925);
  --color-surface-hover:   var(--gray-800);
  --color-surface-active:  var(--gray-750);

  --color-text-primary:    var(--gray-50);    /* Lc 104 on canvas */
  --color-text-secondary:  var(--gray-200);   /* Lc 75+ on ALL surfaces incl hover/active */
  --color-text-tertiary:   var(--gray-400);   /* Lc 60 — floor for text */
  --color-text-disabled:   var(--gray-600);
  --color-text-inverse:    var(--gray-950);
  --color-text-link:       var(--info-text-dark);

  --color-border:          var(--gray-700);
  --color-border-subtle:   var(--gray-800);
  --color-border-strong:   var(--gray-500);

  --color-focus-ring:      var(--info-base-dark);
  --color-text-on-status:  var(--gray-950);

  --color-status-error-bg:       var(--error-bg-dark);
  --color-status-error-border:   var(--error-border-dark);
  --color-status-error:          var(--error-base-dark);
  --color-status-error-text:     var(--error-text-dark);

  --color-status-warning-bg:     var(--warning-bg-dark);
  --color-status-warning-border: var(--warning-border-dark);
  --color-status-warning:        var(--warning-base-dark);
  --color-status-warning-text:   var(--warning-text-dark);

  --color-status-success-bg:     var(--success-bg-dark);
  --color-status-success-border: var(--success-border-dark);
  --color-status-success:        var(--success-base-dark);
  --color-status-success-text:   var(--success-text-dark);

  --color-status-info-bg:        var(--info-bg-dark);
  --color-status-info-border:    var(--info-border-dark);
  --color-status-info:           var(--info-base-dark);
  --color-status-info-text:      var(--info-text-dark);
}

/* ---- Global a11y defaults ---- */
:focus-visible {
  outline: var(--focus-ring-width) solid var(--color-focus-ring);
  outline-offset: var(--focus-ring-offset);
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
